(ns exercises.lesson04.where-state-lives-test
  (:require [cheshire.core :as json]
            [clojure.string :as string]
            [clojure.test :refer [deftest is testing]]
            [hiccup2.core :as h]
            [exercises.lesson04.sse :as sse]
            [exercises.lesson04.where-state-lives :as w])
  (:import (java.io ByteArrayInputStream)))

(defn- html [hiccup] (str (h/html hiccup)))

(defn- patched-signals [body]
  (some-> (re-find #"data: signals (.*)\n" body) second (json/parse-string true)))

(deftest drink-options-view-test
  (testing "a latte: three sizes, three milks, chosen ones selected"
    (let [out (html (w/drink-options-view :latte #{} {:size :medium :milk :oat}))]
      (is (string/starts-with? out "<div id=\"drink-options\">"))
      (is (string/includes? out "<select data-bind:size=\"\" id=\"size\">"))
      (is (string/includes? out "<select data-bind:milk=\"\" id=\"milk\">"))
      (is (= ["small" "medium" "large" "whole" "oat" "almond"]
             (map second (re-seq #"<option[^>]*value=\"(\w+)\"" out))))
      (is (string/includes? out "<option selected=\"\" value=\"medium\">Medium</option>"))
      (is (string/includes? out "<option selected=\"\" value=\"oat\">Oat</option>"))))
  (testing "a sold-out milk is disabled and labelled"
    (let [out (html (w/drink-options-view :latte #{:oat} {:size :small :milk :whole}))]
      (is (string/includes? out "<option disabled=\"\" value=\"oat\">Oat (sold out)</option>"))
      (is (string/includes? out "<option selected=\"\" value=\"whole\">Whole</option>"))))
  (testing "an espresso: two sizes and no milk select"
    (let [out (html (w/drink-options-view :espresso #{} {:size :single :milk nil}))]
      (is (= ["single" "double"] (map second (re-seq #"<option[^>]*value=\"(\w+)\"" out))))
      (is (not (string/includes? out "id=\"milk\"")))
      (is (string/includes? out "<p class=\"muted\">No milk</p>")))))

(deftest drink-options-response-test
  (testing "two events: the elements first, then the signals"
    (let [{:keys [headers body]} (w/drink-options-response {:drink "espresso" :size "small" :milk "whole"} #{})]
      (is (= "text/event-stream" (get headers "Content-Type")))
      (is (< (string/index-of body "event: datastar-patch-elements")
             (string/index-of body "event: datastar-patch-signals")))
      (is (string/includes? body "data: elements <div id=\"drink-options\">"))
      (is (string/includes? body "data: mode replace\n") "replace, so the new selects start fresh")
      (is (= {:size "single" :milk ""} (patched-signals body)))))
  (testing "only invalid signals are patched"
    (is (= {:milk "whole"}
           (patched-signals (:body (w/drink-options-response {:drink "latte" :size "medium" :milk "oat"} #{:oat}))))))
  (testing "nothing changed: an empty patch"
    (is (= {} (patched-signals (:body (w/drink-options-response {:drink "latte" :size "large" :milk "almond"} #{}))))))
  (testing "a chai drops small"
    (is (= {:size "medium"}
           (patched-signals (:body (w/drink-options-response {:drink "chai" :size "small" :milk "whole"} #{}))))))
  (testing "a number where a string belongs is treated as missing, not a 500"
    (is (= 200 (:status (w/drink-options-response {:drink 5 :size true :milk 1} #{}))))))

(deftest add-to-cart-test
  (let [state {:sold-out #{:oat} :carts {"s1" [{:drink :mocha :size :small :milk :whole :qty 1}]}}
        line  {:drink :latte :size :medium :milk :whole :qty 2}]
    (testing "a valid draft goes on the end of that session's cart"
      (is (= [{:drink :mocha :size :small :milk :whole :qty 1} line]
             (get-in (w/add-to-cart state "s1" line) [:carts "s1"]))))
    (testing "a new session gets a new cart"
      (is (= [line] (get-in (w/add-to-cart state "s2" line) [:carts "s2"]))))
    (testing "invalid drafts give nil"
      (is (nil? (w/add-to-cart state "s1" (assoc line :milk :oat))) "sold out")
      (is (nil? (w/add-to-cart state "s1" (assoc line :size :single))) "wrong size")
      (is (nil? (w/add-to-cart state "s1" (assoc line :qty 0))) "bad quantity"))
    (testing "extra keys in the draft do not reach the cart"
      (is (= [line] (get-in (w/add-to-cart state "s3" (assoc line :error "")) [:carts "s3"]))))))

(deftest handlers-test
  (reset! w/state {:sold-out #{} :carts {}})
  (testing "the first page sets a sid cookie"
    (let [resp (w/handler {:request-method :get :uri "/" :headers {}})]
      (is (some #(string/starts-with? % "sid=") (get-in resp [:headers "Set-Cookie"])))))
  (testing "POST /cart/items adds to the cookie's cart and patches #cart"
    (let [req  {:request-method :post :uri "/cart/items"
                :headers        {"cookie" "sid=abc"}
                :body           (ByteArrayInputStream.
                                 (.getBytes "{\"drink\":\"latte\",\"size\":\"medium\",\"milk\":\"oat\",\"qty\":2,\"error\":\"\"}"))}
          body (:body (w/handler req))]
      (is (string/includes? body "data: elements <div id=\"cart\">"))
      (is (string/includes? body "2 × Medium Oat Latte — $11.20"))
      (is (= [{:drink :latte :size :medium :milk :oat :qty 2}] (get-in @w/state [:carts "abc"])))))
  (testing "a refused draft patches #draft-error as HTML, and no signals"
    (let [req  {:request-method :post :uri "/cart/items"
                :headers        {"cookie" "sid=abc"}
                :body           (ByteArrayInputStream.
                                 (.getBytes "{\"drink\":\"espresso\",\"size\":\"double\",\"milk\":\"oat\",\"qty\":1}"))}
          body (:body (w/handler req))]
      (is (string/includes? body "data: elements <p class=\"error\" id=\"draft-error\">Espresso does not take that milk.</p>"))
      (is (not (string/includes? body "datastar-patch-signals")))))
  (testing "a good draft clears #draft-error"
    (let [req  {:request-method :post :uri "/cart/items"
                :headers        {"cookie" "sid=abc"}
                :body           (ByteArrayInputStream.
                                 (.getBytes "{\"drink\":\"mocha\",\"size\":\"small\",\"milk\":\"whole\",\"qty\":1}"))}]
      (is (string/includes? (:body (w/handler req)) "data: elements <p class=\"error\" id=\"draft-error\"></p>")))))

(deftest read-signals-test
  (testing "bad or non-object JSON gives {}"
    (is (= {} (sse/read-signals {:request-method :get :query-params {"datastar" "{oops"}})))
    (is (= {} (sse/read-signals {:request-method :post :body (ByteArrayInputStream. (.getBytes "[1]"))})))
    (is (= {:a 1} (sse/read-signals {:request-method :get :query-params {"datastar" "{\"a\":1}"}})))))
